// CEFFLO Creative Intelligence Layer -- Scenario Validator.
// Source doctrine: docs/cefflo/sot/marketing/11_CREATIVE_INTELLIGENCE_LAYER.md §14 Scenario Validation,
// §15 Anti-Fabrication, §20 Diversity Engine, §29 Hard Guardrails.

// Product-Truth-grounded capability allowlist. Every id must trace to
// docs/cefflo/sot/01_PRODUCT_TRUTH.md §4/§5. "rider_assignment" (not
// "driver_assignment") per the GATE B resolution in vehicle_types.json.
const APPROVED_CEFFLO_CAPABILITIES = [
  'order_organization', 'coverage', 'zones', 'delivery_planning', 'multi_drop_runs',
  'rider_assignment', 'dispatch', 'operational_visibility', 'delivery_status',
  'customer_tracking_where_implemented',
];

const FABRICATION_MARKERS = [
  /\btestimonial\b/i, /\brevenue\b/i, /\bfake\b/i, /\bcustomer\s+count\b/i,
  /\btime\s+saved\b/i, /\bpercent(age)?\s+success\b/i, /\bscreenshot\b/i,
];

function validatePlausibility(scenario) {
  const failures = [];
  const { order_profile, delivery_team } = scenario;
  if (!(order_profile.count > 0)) failures.push('order_profile.count must be positive');
  if (delivery_team.available > delivery_team.expected) failures.push('delivery_team.available cannot exceed expected');
  if (delivery_team.available < 1) failures.push('delivery_team.available must be at least 1');
  return failures;
}

function validateBusinessFit(scenario, taxonomy) {
  const known = taxonomy.businessArchetypes.categories.flatMap((c) => c.archetypes);
  if (!known.includes(scenario.business_archetype.business_type)) {
    return [`unknown business_type: ${scenario.business_archetype.business_type}`];
  }
  return [];
}

function validateVehicleFit(scenario) {
  const failures = [];
  const { vehicle_mix, order_profile } = scenario;
  if (!vehicle_mix.length) failures.push('vehicle_mix must not be empty');
  const totalVehicles = vehicle_mix.reduce((sum, v) => sum + v.count, 0);
  // heuristic plausibility bound, not a capacity optimizer: flag a mix that is wildly
  // out of proportion (e.g. one motorcycle claiming 200 same-window drops).
  const motorcycleCount = vehicle_mix.filter((v) => v.type === 'motorcycle').reduce((s, v) => s + v.count, 0);
  if (motorcycleCount > 0 && !vehicle_mix.some((v) => v.type !== 'motorcycle')) {
    const perMotorcycle = order_profile.count / motorcycleCount;
    if (perMotorcycle > 30) failures.push(`implausible motorcycle-only load: ${order_profile.count} orders across ${motorcycleCount} motorcycle(s)`);
  }
  if (totalVehicles < 1) failures.push('at least one vehicle is required');
  return failures;
}

function validateHumanFit(scenario) {
  return scenario.personas.length ? [] : ['at least one persona is required'];
}

// GATE B resolution check (docs/cefflo/05_DECISIONS.md D-27): the scenario's
// delivery_team.label must match the vehicle-contextual mapping exactly --
// Motorcycle->Rider, Car/Van->Driver, mixed fleet->Delivery Team.
function validateWorkforceLabel(scenario, taxonomy) {
  const types = [...new Set(scenario.vehicle_mix.map((v) => v.type))];
  const expected = types.length > 1
    ? taxonomy.vehicleTypes.mixed_fleet_label
    : taxonomy.vehicleTypes.vehicle_types.find((v) => v.id === types[0])?.natural_language_label;
  if (scenario.delivery_team.label !== expected) {
    return [`delivery_team.label '${scenario.delivery_team.label}' does not match expected '${expected}' for vehicle_mix [${types.join(',')}]`];
  }
  return [];
}

function validateProductFit(scenario) {
  const failures = [];
  for (const capability of scenario.cefflo_relevance) {
    if (!APPROVED_CEFFLO_CAPABILITIES.includes(capability)) {
      failures.push(`cefflo_relevance capability not Product-Truth-approved: ${capability}`);
    }
  }
  return failures;
}

function validateLanguageFit(scenario) {
  const allowed = ['clean_natural', 'everyday_business', 'pasar_beradab'];
  return allowed.includes(scenario.language_context?.register) ? [] : ['language_context.register must be set to an approved register'];
}

function validateCreativeValue(scenario) {
  const hasTension = scenario.emotional_tension.length > 0;
  const hasOpportunity = scenario.creative_opportunities.length > 0;
  return hasTension || hasOpportunity ? [] : ['scenario lacks tension or creative_opportunities -- insufficient creative value'];
}

function validateAntiFabrication(scenario) {
  const failures = [];
  const text = JSON.stringify(scenario);
  for (const marker of FABRICATION_MARKERS) {
    if (marker.test(text)) failures.push(`possible fabrication marker matched: ${marker}`);
  }
  return failures;
}

// Diversity Engine (§20): reject/rotate near-duplicate novelty signatures.
function validateNovelty(scenario, recentSignatures = []) {
  const sig = JSON.stringify(scenario.novelty_signature);
  const isDuplicate = recentSignatures.some((s) => JSON.stringify(s) === sig);
  return isDuplicate ? ['novelty_signature duplicates a recent scenario -- rotate business archetype, persona, vehicle mix, or problem'] : [];
}

function validateScenario(scenario, taxonomy, recentSignatures = []) {
  const checks = {
    PLAUSIBILITY: validatePlausibility(scenario),
    BUSINESS_FIT: validateBusinessFit(scenario, taxonomy),
    VEHICLE_FIT: validateVehicleFit(scenario),
    HUMAN_FIT: validateHumanFit(scenario),
    WORKFORCE_LABEL: validateWorkforceLabel(scenario, taxonomy),
    PRODUCT_FIT: validateProductFit(scenario),
    LANGUAGE_FIT: validateLanguageFit(scenario),
    CREATIVE_VALUE: validateCreativeValue(scenario),
    ANTI_FABRICATION: validateAntiFabrication(scenario),
    NOVELTY: validateNovelty(scenario, recentSignatures),
  };
  const failed_checks = Object.entries(checks).filter(([, v]) => v.length).map(([k]) => k);
  const hard_reject = ['PRODUCT_FIT', 'ANTI_FABRICATION'].some((k) => checks[k].length);
  const status = failed_checks.length === 0 ? 'PASS' : hard_reject ? 'REJECT' : 'REVISE';
  return {
    status,
    failed_checks,
    detail: Object.fromEntries(Object.entries(checks).filter(([, v]) => v.length)),
    scores: {},
  };
}
// CEFFLO Phase 03 Batch 03E -- Pre-/Post-Production QA.
// Source: CEFFLO_PHASE_03_MARKETING_ENGINE_CONTENT_PILOT_MASTER.md §15, §16.
// Extends, does not duplicate, scripts/cil-validate.mjs's scenario-level checks
// (Product Truth allowlist, vehicle realism, anti-fabrication, novelty).

const FORBIDDEN_TERMS = [
  /rider marketplace/i, /driver marketplace/i, /own(s)? (a |the )?rider network/i, /cefflo.{0,20}supplies? (riders|drivers)/i,
  /guaranteed/i, /live gps/i, /automatic route optimi[sz]ation/i, /\d+%\s*(faster|cheaper|savings)/i,
];

const GENERIC_HOOK_PATTERNS = [
  /are you struggling with deliveries/i, /say goodbye to delivery headaches/i, /transform your (business|delivery)/i,
  /work smarter,? not harder/i, /take your business to the next level/i, /revolutioni[sz]e your delivery/i,
];

// §15 Pre-Production QA -- run BEFORE any paid video generation.
function preProductionQA(scenario, contentPackage, taxonomy, recentHooks = []) {
  const failures = [];
  const scenarioResult = validateScenario(scenario, taxonomy, []);
  if (scenarioResult.status !== 'PASS') failures.push(...scenarioResult.failed_checks.map((c) => `scenario:${c}`));

  const text = JSON.stringify(contentPackage);
  for (const term of FORBIDDEN_TERMS) if (term.test(text)) failures.push(`forbidden_claim:${term}`);
  for (const pattern of GENERIC_HOOK_PATTERNS) if (pattern.test(contentPackage.hook?.hook_bm || '')) failures.push('generic_hook');

  // vehicle terminology correctness (§15: "motorcycle/car/van terminology is correct")
  for (const v of scenario.vehicle_mix) {
    const entry = taxonomy.vehicleTypes.vehicle_types.find((t) => t.id === v.type);
    if (!entry) failures.push(`unknown_vehicle_type:${v.type}`);
  }

  const isDuplicateHook = recentHooks.includes(contentPackage.hook?.hook_bm);
  if (isDuplicateHook) failures.push('insufficiently_distinct_from_recent_output');

  if (!contentPackage.script?.cta_bm) failures.push('missing_cta');

  return { status: failures.length ? 'REJECT' : 'PASS', failed_checks: failures, checked_at: new Date().toISOString() };
}

// §16 Post-Production QA -- run AFTER an asset (video/design/product capture) exists.
function postProductionQA(asset, scenario) {
  const failures = [];
  if (!asset) return { status: 'REJECT', failed_checks: ['missing_asset'], checked_at: new Date().toISOString() };

  if (asset.lane === 'video') {
    for (const check of ['natural_human_motion', 'believable_workplace_behavior', 'realistic_vehicles', 'object_continuity', 'scene_consistency']) {
      if (asset.qa_flags?.includes(check)) failures.push(`video:${check}`);
    }
    // §11: motorcycle/car/van correctness carries through from the scenario, not invented at QA time.
    const declaredVehicles = new Set(scenario.vehicle_mix.map((v) => v.type));
    for (const shown of asset.vehicles_shown || []) if (!declaredVehicles.has(shown)) failures.push(`vehicle_mismatch:${shown}`);
  }

  if (asset.claims) {
    for (const claim of asset.claims) {
      if (!APPROVED_CEFFLO_CAPABILITIES.includes(claim)) failures.push(`unapproved_claim:${claim}`);
    }
  }

  if (asset.is_ai_generated_ui) failures.push('ai_generated_product_ui_not_allowed'); // §10.4, §13

  const status = failures.length === 0 ? 'PASS' : failures.some((f) => f.startsWith('unapproved_claim') || f === 'ai_generated_product_ui_not_allowed') ? 'REJECT' : 'REVISE';
  return { status, failed_checks: failures, checked_at: new Date().toISOString() };
}
const packages = input.creative_packages || [];
const expected = ['meta','tiktok','threads'];
const missing = expected.filter((lane) => !packages.some((p) => p.lane === lane));
const preQa = preProductionQA(input.cil_scenario, input.content_package, TAXONOMY, input.recent_hooks || []);
let qa_status = missing.length || preQa.status !== 'PASS' ? 'REVISE' : 'PASS';
const revision = input.qa_fixture?.revision_target || (missing.length ? { stage: 'CREATIVE', lane: missing[0] } : { stage: null, lane: null });
if (input.qa_fixture?.force_status) qa_status = input.qa_fixture.force_status;
const retry = Number(input.retry_count || 0);
if (qa_status === 'REVISE' && retry >= Number(input.max_retries ?? 2)) throw new Error('ERROR_VALIDATION: targeted retry limit exhausted');
return [{ json: { ...input, qa_status, qa_score: qa_status === 'PASS' ? 100 : 60, failed_rules: [...missing.map((x) => 'missing_' + x), ...preQa.failed_checks], qa_feedback: preQa.failed_checks, revision_target: revision, stage: 'AI_QA', status: qa_status === 'PASS' ? 'FOUNDER_REVIEW' : qa_status === 'REJECT' ? 'REJECTED' : 'REVISION_REQUIRED', updated_at: new Date().toISOString() } }];
